# tests/test_discount.py - written and committed BEFORE asking the agent for the code
import pytest

from shop.pricing import apply_discount


def test_percentage_discount():
    assert apply_discount(total_millimes=50_000, code="PROMO10") == 45_000


def test_unknown_code_keeps_price():
    assert apply_discount(total_millimes=50_000, code="NOPE") == 50_000


def test_expired_code_is_rejected():
    with pytest.raises(ValueError, match="expired"):
        apply_discount(total_millimes=50_000, code="SUMMER2023")


def test_result_is_rounded_to_whole_millimes():
    # 10% of 12,345 millimes is 1,234.5: the customer pays 11,111 (rounded half up)
    assert apply_discount(total_millimes=12_345, code="PROMO10") == 11_111

