# tests/test_phone.py - commit these tests first, then ask:
# "Implement normalize_phone so these tests pass. Do not modify the tests."
import pytest

from app.phone import normalize_phone


def test_local_number_with_spaces():
    assert normalize_phone("22 123 456") == "+21622123456"


def test_number_with_country_code():
    assert normalize_phone("+216 98 765 432") == "+21698765432"


def test_number_with_00_prefix():
    assert normalize_phone("00216 55 000 111") == "+21655000111"


def test_too_short_number_is_rejected():
    with pytest.raises(ValueError):
        normalize_phone("22 123")
